head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > setColumnReadOnly]<br/>Column 정보를 사용하여 특정 Column 의 readOnly 속성값을 설정합니다.",
    "validation" : [
        "colInfo(필수) 파라미터로 readOnly 속성을 설정할 특정 Column 의 인덱스를 설정할 수 있어야 합니다.",
        "readOnly 파라미터를 true 로 설정 시 특정 Column 을 읽기 전용(readonly) 상태로 설정해야 합니다.",
        "readOnly 파라미터를 false 로 설정 시 특정 Column 의 읽기 전용(readonly) 상태를 해제해야 합니다.",
        "readOnly 파라미터를 빈 문자열로 설정 시 상위 모듈의 읽기 전용(readonly) 상태가 적용되어야 합니다.",
        "readOnly 파라미터 생략 시 기본값 false 로 동작해야 합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    $c.gcm.createLabel('label="상위 모듈인 GridReadOnly 를 true 로 설정, 두번째 컬럼이 숨겨진 상태"', '', 'label1');

    // 조건 설정
    let properties = {
        dataList: "data:dlt_bind",
        readOnlyBackgroundColor: "#D3D3D3",
    };

    let cList = $c.gcm.createCList(properties);
    let eList = $c.gcm.createEList(["oncelldblclick"]);

    // dataList 생성
    $c.gcm.createBasicDataList('', '', 'dlt_bind');

    // target 생성
    await $c.gcm.createBasicGridView(cList, eList);

    // 두번째 컬럼 숨김
    target1.setColumnVisible(1, false);

    // GridReadOnly 를 true 로 설정
    target1.setGridReadOnly(true);
}



scwin.btn_setColumnReadOnly_onclick = function () {
    let colInfo = Number(par_colInfo.getText());
    let readOnlyText = par_readOnly.getValue();

    if (readOnlyText === 'omit') {
        // 파라미터 생략
        target1.setColumnReadOnly(colInfo);
        wf_body_bottom.getObj("scwin").setReturnValue("setColumnReadOnly(" + colInfo + ")");
    } else if (readOnlyText === '') {
        // 빈 문자열 설정
        target1.setColumnReadOnly(colInfo, "");
        wf_body_bottom.getObj("scwin").setReturnValue("setColumnReadOnly(" + colInfo + ", \"\")");
    } else {
        let readOnly = readOnlyText === 'true';
        target1.setColumnReadOnly(colInfo, readOnly);
        wf_body_bottom.getObj("scwin").setReturnValue("setColumnReadOnly(" + colInfo + ", " + readOnly + ")");
    }

    scwin.btn_getColumnReadOnly_onclick();
}



scwin.btn_getColumnReadOnly_onclick = function () {
    let colInfo = Number(par_colInfo.getText());

    let rtn = target1.getColumnReadOnly(colInfo);
    wf_body_bottom.getObj("scwin").setReturnValue("getColumnReadOnly(" + colInfo + ") : " + rtn);
}



scwin.target1_oncelldblclick = function (row, col) {
    let isEditing = target1.isEditing();
    wf_body_bottom.getObj("scwin").setReturnValue("Cell(" + row + ", " + col + ") dblclick - isEditing : " + isEditing);
}
